//relat.cpp
//demonstrates relational operators
//Comparision of integer variable and constant
#include<iostream>
using namespace std;
int main() 
{
    int numb;
    cout <<"Enter a number";
    cin >> numb;
    cout<<"numb < 10 is " << (numb < 10)<<endl;
    cout<<"numb > 10 is " << (numb > 10)<<endl;
    cout<<"numb == 10 is "<< (numb == 10)<<endl;
    return 0;
}
//here 1 is true and 0 if false

